$("bankImages").addEventListener("change",()=>{const files=[...($("bankImages").files||[])];$("imageSelectionInfo").textContent=files.length+" / 10 photo(s) sélectionnée(s)";if(files.length>10){$("bankImages").value="";$("imageSelectionInfo").textContent="Maximum 10 photos. Sélectionne un nouveau lot.";imageStatus("Tu peux importer 10 photos maximum par analyse.",true)}else if(files.some(f=>!/^image\/(jpeg|png|webp)$/.test(f.type))){$("bankImages").value="";imageStatus("Format non pris en charge. Utilise JPG, PNG ou WebP.",true)}});
$("analyzeImages").addEventListener("click",async()=>{const files=[...($("bankImages").files||[])];if(!files.length)return imageStatus("Sélectionne au moins une photo.",true);if(files.length>10)return imageStatus("10 photos maximum par analyse.",true);if(files.some(f=>f.size>12*1024*1024))return imageStatus("Chaque photo doit peser moins de 12 Mo.",true);if(!window.Tesseract)return imageStatus("Le moteur OCR n'est pas disponible. Vérifie ta connexion puis réessaie.",true);$("analyzeImages").disabled=true;$("imageReview").classList.add("hidden");imageStatus("Lecture locale des photos… Aucune image n'est envoyée au serveur BEP.");const candidates=[];try{for(let i=0;i<files.length;i++){imageStatus("Analyse de la photo "+(i+1)+" sur "+files.length+"…");const result=await window.Tesseract.recognize(files[i],"fra+eng",{logger:m=>{if(m.status==="recognizing text")imageStatus("Photo "+(i+1)+" / "+files.length+" — reconnaissance "+Math.round((m.progress||0)*100)+" %")}});const extracted=imageCandidatesFromOcrData(result.data,files[i].name);for(const c of extracted)candidates.push(c);if(!extracted.length){for(const line of String(result.data?.text||"").split(/\r?\n/)){const c=imageCandidateFromLine(line,files[i].name,false);if(c)candidates.push(c)}}}const seen=new Set();imageCandidates=candidates.filter(c=>{const k=pdfCleanText(c.description)+"|"+c.amount.toFixed(2);if(seen.has(k))return false;seen.add(k);return true});if(!imageCandidates.length)throw Error("Aucune information financière suffisamment lisible n'a été détectée. Essaie avec des captures plus nettes où les libellés et montants sont visibles.");imageCandidateIndex=0;$("bankImages").value="";$("imageSelectionInfo").textContent="Photos analysées. Les fichiers originaux ne sont plus sélectionnés.";imageStatus(imageCandidates.length+" information(s) détectée(s). Vérifie-les une par une.");imageRenderCandidate()}catch(e){$("bankImages").value="";imageStatus(e.message||"L'analyse des photos a échoué.",true)}finally{$("analyzeImages").disabled=false}});

