$("savingsForm").onsubmit=e=>{e.preventDefault();let r=$("savingsRate").value==="suggested"?rate():+$("savingsRate").value,m=totalIncome()*r/100,otherGoals=state.goals.filter(x=>x.id!==editingGoalId).reduce((n,g)=>n+Number(g.monthly||0),0);if(r<=0||m>available()-otherGoals)return notify("Épargne non soutenable avec le budget actuel");const item={id:editingGoalId||crypto.randomUUID(),name:$("goalName").value.trim()||"Mon épargne",rate:r,monthly:m,duration:+$("duration").value};if(editingGoalId){state.goals=state.goals.map(x=>x.id===editingGoalId?item:x);editingGoalId=null;notify("Objectif modifié")}else{state.goals.push(item);notify("Objectif enregistré")}save();$("goalName").value="";$("savingsRate").value="suggested";$("duration").value="3";$("savingsForm").querySelector("button").textContent="Enregistrer mon engagement";preview()};
