async function submitCoachQuestion(question){
 const value=String(question||"").trim();if(!value)return;addCoachMessage("user",value);
 if(window.bepSignedIn&&aiConnection.configured){addCoachMessage("coach","Le Coach BEP prépare sa réponse…");const log=$("coachChatLog"),last=log?.lastElementChild;try{const r=await fetch(API+"/api/ai/chat",{method:"POST",credentials:"include",headers:{"Content-Type":"application/json"},body:JSON.stringify({question:value,financialContext:{income:totalIncome(),charges:charges(),available:available(),budgets:state.budgets,goals:state.goals,expenses:(state.expenses||[]).slice(0,30)}})}),d=await r.json();if(!r.ok)throw Error(d.message||"IA indisponible.");const p=last?.querySelector("p");if(p)p.textContent=d.answer;else addCoachMessage("coach",d.answer)}catch(e){const p=last?.querySelector("p");if(p)p.textContent="Le fournisseur IA n'a pas répondu : "+e.message+" Le moteur local reste disponible."}}else addCoachMessage("coach",coachReply(value));
}
